[
  {
    "name": "柳白衣",
    "description": "进京赶考的书生，本片主角，七日茶馆之约的闯入者",
    "appearance": "二十出头，眉目清俊温润，肤色白皙，唇色浅淡",
    "costume": "月白色交领长衫，外罩青灰鹤氅，腰束墨色布带，头戴玉冠束发",
    "personality": "胆大心细、重情义，有士人风骨却不迂腐"
  },
  {
    "name": "茶馆老妪",
    "description": "茶馆神秘主人，似人非人，知道书生前世",
    "appearance": "苍老妇人，满头银发挽成低髻，眼窝深陷，瞳色琥珀",
    "costume": "酱紫色斜襟布衣，外披灰白披帛，腕缠红绳",
    "personality": "慈祥中藏着威压，话不多却句句机锋"
  },
  {
    "name": "阿璃",
    "description": "狐妖少女，黑猫化形，活泼好奇，是书生在茶馆遇到的第一个异类",
    "appearance": "十六七岁少女，鹅蛋脸，眼大而亮，瞳色金黄，颊边一缕黑发",
    "costume": "鸦青色短褙子配石榴红马面裙，颈挂银铃，脚踩木屐",
    "personality": "灵动跳脱、贪玩任性，对人间充满好奇"
  },
  {
    "name": "地底巨影",
    "description": "第七夜出现的恐怖存在，书生前世之谜的关键",
    "appearance": "模糊人形的黑色巨影，仅露出一双血红瞳孔",
    "costume": "无实体，仅黑雾缠绕",
    "personality": "沉默、压迫、似有深仇"
  }
]

[
  {
    "name": "雨夜荒村入口",
    "description": "书生迷途偶遇茶馆灯笼的起点",
    "visualStyle": "暴雨如注，泥泞土路，远处唯一点橘红灯笼，色调冷青"
  },
  {
    "name": "狐隐茶馆·大堂",
    "description": "故事主舞台，木构老宅，挂满褪色灯笼与字画",
    "visualStyle": "暖黄灯笼光，檀香木桌，老式黄铜茶壶，蒸汽缭绕"
  },
  {
    "name": "茶馆二楼客房",
    "description": "书生留宿之所，推窗可见山林",
    "visualStyle": "月光青白透窗，木地板反光，薄纱帐幔轻摇"
  },
  {
    "name": "茶馆后院",
    "description": "阿璃化形之处，有古井与枯藤",
    "visualStyle": "夜色浓稠，月光斑驳，青苔湿滑，井口冒白雾"
  }
]

{
  "scenes": [
    {
      "location": "雨夜荒村入口",
      "time": "夜晚·暴雨",
      "characters": [
        "柳白衣"
      ],
      "action": "柳白衣撑伞踉跄于泥路，远处忽现一盏橘红灯笼，他抬头环顾后决意推门",
      "dialogue": "（远处传来古琴残音）",
      "mood": "孤绝、诡秘、宿命感初现"
    },
    {
      "location": "狐隐茶馆·大堂",
      "time": "夜晚",
      "characters": [
        "柳白衣",
        "茶馆老妪"
      ],
      "action": "柳白衣推门而入，老妪无声端上热茶，他环顾客堂发现满墙字画皆是狐仙",
      "dialogue": "柳白衣：店家，可有借宿之处？ 老妪：（笑而不语，只推茶）",
      "mood": "静谧、悬疑、暖光包裹的诡异"
    },
    {
      "location": "狐隐茶馆·大堂",
      "time": "夜晚",
      "characters": [
        "柳白衣",
        "阿璃"
      ],
      "action": "一只黑猫跃上桌面化出少女阿璃，柳白衣惊退半步，茶盏倾倒",
      "dialogue": "阿璃：又来一个书呆子！",
      "mood": "惊悚、灵动感、突发的反差萌"
    },
    {
      "location": "茶馆后院",
      "time": "夜晚",
      "characters": [
        "柳白衣",
        "阿璃"
      ],
      "action": "阿璃拽柳白衣到后院，指着古井说井底住着大东西，今晚别靠近",
      "dialogue": "阿璃：听——它在翻身呢。",
      "mood": "调皮中透着不安，神秘感抬升"
    },
    {
      "location": "茶馆二楼客房",
      "time": "深夜",
      "characters": [
        "柳白衣"
      ],
      "action": "柳白衣独坐窗前翻书，却无法入眠；楼下传来细碎声响，地底隐隐震颤",
      "dialogue": "（无对白，仅木楼吱呀声与心跳声）",
      "mood": "压抑、内心独白式的孤悬感"
    },
    {
      "location": "狐隐茶馆·大堂",
      "time": "深夜",
      "characters": [
        "茶馆老妪",
        "阿璃"
      ],
      "action": "老妪立在暗处凝视楼梯口，阿璃蹲在桌角，两人对视，无言。画面定格在地底涌出的暗流上",
      "dialogue": "老妪：第一夜……算他过了。",
      "mood": "仪式感、倒计时开启、悬疑封顶"
    }
  ]
}
